const styles=['Organic modern','Mid-century','Minimalist','Industrial','Coastal','Eclectic'];
const palettes=[{name:'Earth & olive',colors:['#52634b','#b79469','#eee5d3'],finish:'walnut',fabric:'olive'},{name:'Warm neutrals',colors:['#c3ab8d','#e4d7c6','#8b6b54'],finish:'oak',fabric:'oatmeal'},{name:'Monochrome',colors:['#303430','#a4a6a1','#e8e9e4'],finish:'black-stained wood',fabric:'charcoal'},{name:'Coastal blues',colors:['#526d83','#a9bdc6','#ede3cc'],finish:'light oak',fabric:'slate blue'}];
let palette=0,current,variants=[0,0,0,0];const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
document.querySelector('#vibes').innerHTML=styles.map((s,i)=>`<div class="choice"><input type="radio" name="vibe" id="v${i}" value="${s}" ${i===0?'checked':''}><label for="v${i}">${s}</label></div>`).join('');
function palettesRender(){document.querySelector('#palettes').innerHTML=palettes.map((p,i)=>`<button type="button" class="palette" aria-label="${p.name}" aria-pressed="${i===palette}" data-palette="${i}">${p.colors.map(c=>`<span class="swatch" style="background:${c}"></span>`).join('')}</button>`).join('');document.querySelector('#palette-name').textContent=palettes[palette].name;}palettesRender();
document.querySelector('#palettes').addEventListener('click',e=>{const b=e.target.closest('button');if(b){palette=Number(b.dataset.palette);palettesRender();}});
const budget=document.querySelector('#budget'),range=document.querySelector('#range');budget.addEventListener('input',()=>range.value=budget.value);range.addEventListener('input',()=>budget.value=range.value);
const rooms={'Living room':[['Sofa','Low-profile sofa','Rounded loveseat'],['Coffee table','Oval coffee table','Nesting tables'],['Accent chair','Lounge chair','Sling chair'],['Rug','Textured area rug','Flatweave rug']],'Bedroom':[['Bed frame','Upholstered bed frame','Platform bed frame'],['Nightstands','Pair of nightstands','Pair of bedside tables'],['Dresser','Low dresser','Tall chest'],['Rug','Soft bedside rug','Flatweave area rug']],'Home office':[['Desk','Writing desk','Compact work desk'],['Chair','Adjustable task chair','Ergonomic office chair'],['Storage','Low storage cabinet','Open bookcase'],['Lighting','Adjustable desk lamp','Task floor lamp']]};
const details={'Organic modern':['Soft curves','Rounded edges','Sculptural silhouette','Natural texture'],'Mid-century':['Tapered legs','Clean lines','Retro profile','Geometric detail'],'Minimalist':['Simple profile','Slim silhouette','Understated shape','Quiet texture'],'Industrial':['Structured shape','Metal details','Exposed frame','Durable texture'],'Coastal':['Relaxed shape','Airy silhouette','Open details','Woven texture'],'Eclectic':['Expressive shape','Playful proportions','Statement profile','Patterned texture']};
function render(){const {room,vibe,total,p}=current;const weights=[.43,.19,.18,.10];const allocations=weights.map(w=>Math.floor(total*w/5)*5);const spent=allocations.reduce((a,b)=>a+b,0);document.querySelector('#results').innerHTML=`<div class="results-head"><div><p class="eyebrow">Your personal edit · ${room}</p><h2>${vibe}, ${p.name.toLowerCase()}</h2></div><span class="badge">Within your ${money(total)} budget</span></div><p class="description">${p.fabric[0].toUpperCase()+p.fabric.slice(1)} tones, ${p.finish}, and ${details[vibe][3].toLowerCase()}. Four pieces that work together, with room left for the finishing touches.</p><div class="cards">${rooms[room].map((r,i)=>`<article class="card"><div class="card-top"><span>0${i+1} / ${r[0].toUpperCase()}</span><span class="material" style="background:${p.colors[i%3]}"></span></div><h3>${r[1+variants[i]]}</h3><p>${details[vibe][i]}. ${i===0||i===3?p.fabric+' tones':p.finish+' finish'} to tie the room together.</p><div class="card-bottom"><span class="price">${money(allocations[i])}<span style="font-size:12px;color:#727a70"> target</span></span><button class="swap" data-swap="${i}" aria-label="Swap ${r[0]} idea">Swap idea ↻</button></div></article>`).join('')}</div><div class="summary"><div><span style="font-size:14px">Furniture spending target</span><p>${money(total-spent)} reserved for delivery, tax & extras</p></div><strong>${money(spent)}</strong></div><p class="note">These are suggested furniture types and budget allocations, not product listings or price quotes.${room==='Bedroom'?' Mattress and bedding are not included.':''} ${total<800?'At this budget, prioritize secondhand pieces and check local availability.':''} The inspiration photo is illustrative and does not change with your selections.</p>`;}
document.querySelector('#results').addEventListener('click',e=>{const b=e.target.closest('[data-swap]');if(b){const i=Number(b.dataset.swap);variants[i]=1-variants[i];render();document.querySelector(`[data-swap="${i}"]`).focus();}});
function generate(){current={room:document.querySelector('#room').value,vibe:document.querySelector('input[name=vibe]:checked').value,total:Number(budget.value),p:palettes[palette]};variants=[0,0,0,0];render();}
document.querySelector('#preferences').addEventListener('submit',e=>{e.preventDefault();generate();if(innerWidth<641)document.querySelector('#results').scrollIntoView({behavior:'smooth',block:'start'});});generate();
